package com.primehr.rsp.evaluation.application;
import com.fasterxml.jackson.core.*; import com.fasterxml.jackson.databind.*; import com.primehr.rsp.applicant.domain.*; import com.primehr.rsp.applicant.infrastructure.*; import com.primehr.rsp.domain.*; import com.primehr.rsp.evaluation.api.CommitteeDtos.CommitteeResponse; import com.primehr.rsp.evaluation.api.EvaluationProceedingDtos.*; import com.primehr.rsp.evaluation.domain.*; import com.primehr.rsp.evaluation.infrastructure.*; import com.primehr.rsp.infrastructure.*; import com.primehr.rsp.screening.domain.*; import com.primehr.rsp.screening.infrastructure.*; import com.primehr.shared.api.*; import com.primehr.shared.audit.*; import com.primehr.shared.exception.*; import org.springframework.data.domain.*; import org.springframework.security.access.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import java.nio.charset.*; import java.security.*; import java.time.*; import java.util.*;
@Service @Transactional public class EvaluationProceedingServiceImpl implements EvaluationProceedingService {
 private final EvaluationProceedingRepository proceedings;private final EvaluationCandidateRepository candidates;private final VacancyPublicationRepository publications;private final PublicationEvaluationPolicyRepository bindings;private final CommitteeRepository committees;private final CommitteeMemberRepository members;private final PositionApplicationRepository applications;private final ScreeningCaseRepository screening;private final CommitteeService committeeService;private final ObjectMapper json;private final PrimeHrAuditService audit;
 public EvaluationProceedingServiceImpl(EvaluationProceedingRepository p,EvaluationCandidateRepository c,VacancyPublicationRepository v,PublicationEvaluationPolicyRepository b,CommitteeRepository cr,CommitteeMemberRepository m,PositionApplicationRepository a,ScreeningCaseRepository s,CommitteeService cs,ObjectMapper j,PrimeHrAuditService au){proceedings=p;candidates=c;publications=v;bindings=b;committees=cr;members=m;applications=a;screening=s;committeeService=cs;json=j;audit=au;}
 @Override @Transactional(readOnly=true)public PageResponse<ProceedingResponse> list(String agency,String actor,int page,int size){page(page,size);return PageResponse.from(proceedings.findPermitted(agency,actor,false,PageRequest.of(page,size,Sort.by("createdAt").descending())),this::response);}
 @Override @Transactional(readOnly=true)public ProceedingResponse get(String agency,String id,String actor){EvaluationProceeding p=proceeding(agency,id);requireMember(p,actor,false);return response(p);}
 @Override public ProceedingResponse create(String agency,CreateProceeding r,String actor,String correlation){VacancyPublication publication=publications.findByIdAndAgencyId(r.publicationId(),agency).orElseThrow(()->new ResourceNotFoundException("Vacancy publication not found"));version(publication.getVersion(),r.publicationRecordVersion());if(publication.getStatus()!=VacancyPublicationStatus.PUBLISHED&&publication.getStatus()!=VacancyPublicationStatus.CLOSED)throw new IllegalArgumentException("Only a PUBLISHED or CLOSED vacancy can enter evaluation");if(r.plannedAsOfDate().isBefore(publication.getClosingDate()))throw new IllegalArgumentException("Evaluation cannot be planned before the vacancy closes");if(proceedings.existsByAgencyIdAndCurrentPublicationKey(agency,publication.getId()))throw new ApplicationConflictException("A current evaluation proceeding already exists for this publication");PublicationEvaluationPolicy binding=bindings.findByAgencyIdAndPublicationId(agency,publication.getId()).orElseThrow(()->new ApplicationConflictException("The vacancy has no evaluation policy binding"));if(!binding.getPolicy().effectiveOn(publication.getClosingDate()))throw new ApplicationConflictException("The bound evaluation policy is not effective for the vacancy closing date");Committee committee=committees.findByIdAndAgencyId(r.committeeId(),agency).orElseThrow(()->new ResourceNotFoundException("Committee not found"));version(committee.getVersion(),r.committeeRecordVersion());if(!committee.effectiveOn(r.plannedAsOfDate()))throw new ApplicationConflictException("The committee is not effective on the planned date");List<CommitteeMember> roster=members.findByAgencyIdAndCommitteeIdOrderByRoleAscEmployeeNoAsc(agency,committee.getId());CommitteeServiceImpl.validateEffectiveRoster(committee,roster,r.plannedAsOfDate());requireCoordinator(agency,committee.getId(),actor,r.plannedAsOfDate());String vacancy=serialize(vacancySnapshot(publication));String committeeSnapshot=serialize(committeeService.get(agency,committee.getId()));EvaluationProceeding p=proceedings.saveAndFlush(new EvaluationProceeding(agency,publication,binding,committee,r.plannedAsOfDate(),vacancy,binding.getPolicySnapshot(),committeeSnapshot,hash(vacancy),binding.getPolicyFingerprint(),hash(committeeSnapshot)));ProceedingResponse after=response(p);audit.record(agency,"CREATE_EVALUATION_PROCEEDING_DRAFT","RSP_EVALUATION_PROCEEDING",p.getId(),null,p.getVersion(),null,after,null,correlation);return after;}
 @Override public ProceedingResponse admit(String agency,String id,AdmitCandidates r,String actor,String correlation){EvaluationProceeding p=proceeding(agency,id);version(p.getVersion(),r.proceedingRecordVersion());p.requireDraft();requireCoordinator(agency,p.getCommittee().getId(),actor,p.getPlannedAsOfDate());Set<String> supplied=new HashSet<>();List<EvaluationCandidate> additions=new ArrayList<>();for(CandidateInput input:r.candidates()){if(!supplied.add(input.applicationId()))throw new IllegalArgumentException("Duplicate application in admission request");if(candidates.existsByAgencyIdAndProceedingIdAndApplicationId(agency,id,input.applicationId()))throw new ApplicationConflictException("Application is already admitted");PositionApplication application=applications.findByIdAndAgencyId(input.applicationId(),agency).orElseThrow(()->new ResourceNotFoundException("Application not found"));version(application.getVersion(),input.applicationRecordVersion());if(application.getStatus()!=PositionApplication.Status.QUALIFIED)throw new ApplicationConflictException("Only a current QUALIFIED application may be admitted");if(!application.getPublication().getId().equals(p.getPublication().getId()))throw new ApplicationConflictException("Application belongs to a different vacancy publication");ScreeningCase current=screening.findByAgencyIdAndApplicationIdAndCurrentApplicationKeyIsNotNull(agency,application.getId()).orElseThrow(()->new ApplicationConflictException("A current final screening case is required"));version(current.getVersion(),input.screeningCaseRecordVersion());if(current.getStatus()!=ScreeningCase.Status.QUALIFIED||!current.isCurrent())throw new ApplicationConflictException("Only a current QUALIFIED screening case may be admitted");String app=serialize(applicationSnapshot(application));String screen=serialize(screeningSnapshot(current));additions.add(new EvaluationCandidate(agency,p,application,current,app,screen,hash(app),hash(screen),actor,Instant.now()));}candidates.saveAll(additions);p.candidatesChanged();p=proceedings.saveAndFlush(p);ProceedingResponse after=response(p);audit.record(agency,"ADMIT_EVALUATION_CANDIDATES","RSP_EVALUATION_PROCEEDING",id,null,p.getVersion(),null,after,"Admitted "+additions.size()+" qualified candidate(s)",correlation);return after;}
 @Override public ProceedingResponse open(String agency,String id,Transition r,String actor,String correlation){EvaluationProceeding p=proceeding(agency,id);version(p.getVersion(),r.recordVersion());requireCoordinator(agency,p.getCommittee().getId(),actor,p.getPlannedAsOfDate());if(candidates.countByAgencyIdAndProceedingId(agency,id)==0)throw new ApplicationConflictException("At least one qualified candidate is required");requireFresh(p);ProceedingResponse before=response(p);p.open(actor,Instant.now());p=proceedings.saveAndFlush(p);ProceedingResponse after=response(p);audit.record(agency,"OPEN_EVALUATION_PROCEEDING","RSP_EVALUATION_PROCEEDING",id,null,p.getVersion(),before,after,null,correlation);return after;}
 @Override public ProceedingResponse cancel(String agency,String id,Transition r,String actor,String correlation){EvaluationProceeding p=proceeding(agency,id);version(p.getVersion(),r.recordVersion());requireCoordinator(agency,p.getCommittee().getId(),actor,p.getPlannedAsOfDate());ProceedingResponse before=response(p);p.cancel(actor,r.reason(),Instant.now());p=proceedings.saveAndFlush(p);ProceedingResponse after=response(p);audit.record(agency,"CANCEL_EVALUATION_PROCEEDING","RSP_EVALUATION_PROCEEDING",id,null,p.getVersion(),before,after,r.reason(),correlation);return after;}
 private void requireFresh(EvaluationProceeding p){
  if(!hash(serialize(vacancySnapshot(p.getPublication()))).equals(p.getVacancyFingerprint()))throw new ApplicationConflictException("The vacancy source changed after the proceeding snapshot was created");
  if(!p.getBinding().getPolicyFingerprint().equals(p.getPolicyFingerprint())||!hash(p.getBinding().getPolicySnapshot()).equals(p.getPolicyFingerprint()))throw new ApplicationConflictException("The bound evaluation policy snapshot no longer matches the proceeding");
  if(!p.getBinding().getPolicy().effectiveOn(p.getPublication().getClosingDate()))throw new ApplicationConflictException("Evaluation policy source is no longer effective for the vacancy closing date");
  if(!p.getCommittee().effectiveOn(p.getPlannedAsOfDate()))throw new ApplicationConflictException("Committee source is no longer effective for the planned date");
  CommitteeServiceImpl.validateEffectiveRoster(p.getCommittee(),members.findByAgencyIdAndCommitteeIdOrderByRoleAscEmployeeNoAsc(p.getAgencyId(),p.getCommittee().getId()),p.getPlannedAsOfDate());
  if(!hash(serialize(committeeService.get(p.getAgencyId(),p.getCommittee().getId()))).equals(p.getCommitteeFingerprint()))throw new ApplicationConflictException("The committee source changed after the proceeding snapshot was created");
  for(EvaluationCandidate c:candidates.findByAgencyIdAndProceedingIdOrderByAdmittedAtAsc(p.getAgencyId(),p.getId())){
   if(c.getApplication().getStatus()!=PositionApplication.Status.QUALIFIED||!c.getScreeningCase().isCurrent()||c.getScreeningCase().getStatus()!=ScreeningCase.Status.QUALIFIED)throw new ApplicationConflictException("An admitted candidate no longer matches the current qualified source");
   if(!hash(serialize(applicationSnapshot(c.getApplication()))).equals(c.getApplicationFingerprint())||!hash(serialize(screeningSnapshot(c.getScreeningCase()))).equals(c.getScreeningFingerprint()))throw new ApplicationConflictException("An admitted candidate source changed after admission");
  }
 }
 private void requireMember(EvaluationProceeding p,String actor,boolean coordinator){CommitteeMember m=members.findEffective(p.getAgencyId(),p.getCommittee().getId(),actor,p.getPlannedAsOfDate()).orElseThrow(()->new AccessDeniedException("Only an effective assigned HRMPSB member may access this proceeding"));if(coordinator&&m.getRole()!=CommitteeMember.Role.CHAIRPERSON&&m.getRole()!=CommitteeMember.Role.VICE_CHAIRPERSON&&m.getRole()!=CommitteeMember.Role.SECRETARIAT)throw new AccessDeniedException("Only the effective chair, vice-chair, or secretariat may manage this proceeding");}
 private void requireCoordinator(String agency,String committee,String actor,LocalDate date){CommitteeMember m=members.findEffective(agency,committee,actor,date).orElseThrow(()->new AccessDeniedException("Only an effective assigned HRMPSB member may manage this proceeding"));if(m.getRole()!=CommitteeMember.Role.CHAIRPERSON&&m.getRole()!=CommitteeMember.Role.VICE_CHAIRPERSON&&m.getRole()!=CommitteeMember.Role.SECRETARIAT)throw new AccessDeniedException("Only the effective chair, vice-chair, or secretariat may manage this proceeding");}
 private ProceedingResponse response(EvaluationProceeding p){List<CandidateResponse> cs=candidates.findByAgencyIdAndProceedingIdOrderByAdmittedAtAsc(p.getAgencyId(),p.getId()).stream().map(c->new CandidateResponse(c.getId(),c.getApplication().getId(),c.getApplicantId(),c.getScreeningCase().getId(),c.getStatus().name(),c.getApplicationVersion(),c.getScreeningCaseRevision(),c.getApplicationFingerprint(),c.getScreeningFingerprint(),c.getAdmittedBy(),c.getAdmittedAt(),c.getVersion())).toList();return new ProceedingResponse(p.getId(),p.getPublication().getId(),p.getBinding().getPolicy().getId(),p.getBinding().getPolicy().getDefinitionVersion(),p.getCommittee().getId(),p.getCommittee().getDefinitionVersion(),p.getPlannedAsOfDate(),p.getStatus().name(),p.getCandidateSetRevision(),p.getVacancyFingerprint(),p.getPolicyFingerprint(),p.getCommitteeFingerprint(),p.getVacancySnapshot(),p.getPolicySnapshot(),p.getCommitteeSnapshot(),p.getOpenedBy(),p.getOpenedAt(),p.getCancelledBy(),p.getCancelledAt(),p.getCancellationReason(),p.getVersion(),cs);}
 private Map<String,Object> vacancySnapshot(VacancyPublication v){Map<String,Object> m=new LinkedHashMap<>();m.put("publicationId",v.getId());m.put("recordVersion",v.getVersion());m.put("status",v.getStatus());m.put("openingDate",v.getOpeningDate());m.put("closingDate",v.getClosingDate());m.put("plantillaId",v.getPlantillaId());m.put("plantillaName",v.getPlantillaName());m.put("jobPositionId",v.getJobPositionId());m.put("jobPositionName",v.getJobPositionName());m.put("salaryGrade",v.getSalaryGrade());m.put("salaryStep",v.getSalaryStep());m.put("qualificationStandardId",v.getQualificationStandardId());m.put("qualificationStandardVersion",v.getQualificationStandardVersion());m.put("positionProfileId",v.getPositionProfileId());m.put("positionProfileDefinitionVersion",v.getPositionProfileDefinitionVersion());m.put("positionProfileRecordRevision",v.getPositionProfileRecordRevision());m.put("administrativeFingerprint",v.getAdministrativeFingerprint());m.put("hrmFingerprint",v.getHrmFingerprint());return m;}
 private Map<String,Object> applicationSnapshot(PositionApplication a){Map<String,Object> m=new LinkedHashMap<>();m.put("applicationId",a.getId());m.put("recordVersion",a.getVersion());m.put("applicationVersion",a.getApplicationVersion());m.put("applicantId",a.getApplicantId());m.put("publicationId",a.getPublication().getId());m.put("status",a.getStatus());m.put("submittedAt",a.getSubmittedAt());m.put("acknowledgmentNumber",a.getAcknowledgmentNumber());m.put("vacancySnapshot",a.getVacancySnapshot());m.put("qualificationSnapshot",a.getQualificationSnapshot());m.put("competencySnapshot",a.getCompetencySnapshot());m.put("profileSnapshot",a.getProfileSnapshot());return m;}
 private Map<String,Object> screeningSnapshot(ScreeningCase s){Map<String,Object> m=new LinkedHashMap<>();m.put("screeningCaseId",s.getId());m.put("recordVersion",s.getVersion());m.put("caseRevision",s.getCaseRevision());m.put("status",s.getStatus());m.put("policyId",s.getPolicyId());m.put("policyDefinitionVersion",s.getPolicyDefinitionVersion());m.put("finalizedBy",s.getFinalizedBy());m.put("finalizedAt",s.getFinalizedAt());m.put("applicationSnapshot",s.getApplicationSnapshot());m.put("policySnapshot",s.getPolicySnapshot());return m;}
 private EvaluationProceeding proceeding(String agency,String id){return proceedings.findByIdAndAgencyId(id,agency).orElseThrow(()->new ResourceNotFoundException("Evaluation proceeding not found"));}private static void page(int p,int s){if(p<0||s<1||s>100)throw new IllegalArgumentException("Invalid pagination");}private static void version(long a,Long e){if(e==null||a!=e)throw new OptimisticConflictException("Expected recordVersion "+e+" but current version is "+a);}private String serialize(Object value){try{return json.writeValueAsString(value);}catch(JsonProcessingException e){throw new IllegalStateException("Snapshot could not be serialized",e);}}private static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
